    evo = matrix_bundle_evolution([{"at": AT1, "bundle": bundle}])
    proof = evolution_checkpoint(evo, AT1, AT1)
    good = evolution_checkpoint_bundle([{"id": "a", "proof": proof}])
    return good, proof


def replace_nth_key(obj, target_key, replacement, nth):
    """Rebuild obj replacing the nth (1-based) dict key equal to target_key."""
    state = {"count": 0}

    def walk(node):
        if isinstance(node, dict):
            new = {}
            for k, v in node.items():
                if k == target_key:
                    state["count"] += 1
                    if state["count"] == nth:
                        k = replacement
                new[k] = walk(v)
            return new
        if isinstance(node, list):
            return [walk(v) for v in node]
        return node

    return walk(obj)


def replace_nth_list(obj, nth):
    state = {"count": 0}

    def walk(node):
        if isinstance(node, list) and len(node) >= 1 and isinstance(
            node[0], dict
        ) and "facts" in node[0]:
            state["count"] += 1
            if state["count"] == nth:
                return tuple(walk(v) for v in node)
            return [walk(v) for v in node]
        if isinstance(node, dict):
            return {k: walk(v) for k, v in node.items()}
        if isinstance(node, list):
            return [walk(v) for v in node]
        return node

    return walk(obj)


