    # but the bug is cross-node reuse within one diff call).
    illegal_bundle = {
        "root": "0" * 64,
        "proofs": [
            {"id": "a", "proof": copy.deepcopy(proof),
             "previous": "0" * 64, "digest": "0" * 64},
            {"id": "b", "proof": bad_proof,
             "previous": "0" * 64, "digest": "0" * 64},
        ],
    }
    # NOTE: bundle structure itself will be structurally walked; the int-key
    # credential is the *second* occurrence of the same JSON text after a
    # valid one -> cache fold.
    try:
        result = evolution_checkpoint_bundle_diff(good, illegal_bundle)
        print("GEN int-key: NO ERROR (BUG), produced diff digest",
              result["digest"][:12])
    except ValueError as exc:
        print("GEN int-key: ValueError OK ->", str(exc)[:80])

    # tuple-where-array collision: cases passed as a tuple in second occurrence
    tuple_proof = replace_nth_list(copy.deepcopy(proof), 1)
    tuple_bundle = {
        "root": "0" * 64,
        "proofs": [
            {"id": "a", "proof": copy.deepcopy(proof),
             "previous": "0" * 64, "digest": "0" * 64},
            {"id": "b", "proof": tuple_proof,
             "previous": "0" * 64, "digest": "0" * 64},
        ],
    }
    try:
        result = evolution_checkpoint_bundle_diff(good, tuple_bundle)
        print("GEN tuple: NO ERROR (BUG), produced diff digest",
              result["digest"][:12])
    except ValueError as exc:
        print("GEN tuple: ValueError OK ->", str(exc)[:80])


if __name__ == "__main__":
    main()

