"""Scratch reproduction of the type-collision reuse bug.

The collision: an int fact key 1 and a str fact key "1" produce identical
JSON bytes, so every declared digest stays byte-correct. The only detectable
problem is Python-level structure validation, which the reuse cache skips.
"""
import copy
import json

import regulation_policy_compiler.policy as P
from regulation_policy_compiler.policy import (
    decision_matrix_attestation,
    decision_matrix_attestation_bundle,
    evolution_checkpoint,
    evolution_checkpoint_bundle,
    evolution_checkpoint_bundle_diff,
    matrix_bundle_evolution,
    verify_evolution_checkpoint_bundle_diff,
)

START = "2021-01-01T00:00:00Z"
END = "2021-04-01T00:00:00Z"
AT1 = "2021-05-01T00:00:00Z"


def _rule(**overrides):
    rule = {
        "id": "r1", "ver": 1, "source": "law", "priority": 0,
        "from": "2020-01-01T00:00:00Z", "to": None,
        "when": None, "result": "allow",
    }
    rule.update(overrides)
    return rule


def good_proof():
    report = decision_matrix_attestation(
        START, END, [{"id": "c1", "facts": {"1": True}}], [_rule()]
    )
    bundle = decision_matrix_attestation_bundle([{"id": "a", "report": report}])
    evo = matrix_bundle_evolution([{"at": AT1, "bundle": bundle}])
    return evolution_checkpoint(evo, AT1, AT1)


def splice_int_key(obj):
    """Replace the facts key '1' with int 1 at the first facts map found."""
    if isinstance(obj, dict):
        if "facts" in obj and isinstance(obj["facts"], dict) and "1" in obj["facts"]:
            return {
                ("__facts__" if False else k):
                (
                    {1: v["1"]} if k == "facts" and list(v) == ["1"]
                    else splice_int_key(v)
                )
                for k, v in obj.items()
            }
        return {k: splice_int_key(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [splice_int_key(v) for v in obj]
    return obj


def splice_tuple_cases(obj):
    """Replace the first cases list with a tuple."""
    if isinstance(obj, dict):
        if "cases" in obj and isinstance(obj["cases"], list):
            return {
                k: (
                    tuple(splice_tuple_cases(v)) if False else
                    tuple(splice_tuple_cases(v)) if k == "cases" and (
                        not v or isinstance(v[0], dict) and "id" in v[0]
                        and "facts" in v[0] and "decision" not in v[0]
                    )
                    else splice_tuple_cases(v)
                )
                for k, v in obj.items()
            }
        return {k: splice_tuple_cases(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [splice_tuple_cases(v) for v in obj]
    return obj


def main():
    proof = good_proof()
    # valid 1-member and 2-member bundles (same proof repeated, distinct ids)
    before = evolution_checkpoint_bundle([{"id": "a", "proof": proof}])
    after_ok = evolution_checkpoint_bundle([
        {"id": "a", "proof": copy.deepcopy(proof)},
        {"id": "b", "proof": copy.deepcopy(proof)},
    ])

    # --- int key collision in member b's proof (JSON bytes identical) ---
    after_int = copy.deepcopy(after_ok)
    after_int["proofs"][1]["proof"] = splice_int_key(
        copy.deepcopy(after_int["proofs"][1]["proof"])
    )
    intkey = after_int["proofs"][1]["proof"]["stages"][0]["bundle"][
        "reports"][0]["report"]["cases"][0]["facts"]
    assert list(intkey) == [1] and isinstance(list(intkey)[0], int)

    try:
        d = evolution_checkpoint_bundle_diff(before, after_int)
        print("GEN int-key : NO ERROR (BUG) digest", d["digest"][:12])
    except ValueError as exc:
        print("GEN int-key : ValueError OK ->", str(exc)[:70])

    # --- tuple cases collision ---
    after_tup = copy.deepcopy(after_ok)
    after_tup["proofs"][1]["proof"] = splice_tuple_cases(
        copy.deepcopy(after_tup["proofs"][1]["proof"])
    )
    t = after_tup["proofs"][1]["proof"]["stages"][0]["bundle"][
        "reports"][0]["report"]["cases"]
    assert isinstance(t, tuple)

    try:
        d = evolution_checkpoint_bundle_diff(before, after_tup)
        print("GEN tuple   : NO ERROR (BUG) digest", d["digest"][:12])
    except ValueError as exc:
        print("GEN tuple   : ValueError OK ->", str(exc)[:70])

    # --- verify side: legal diff, then splice int key into change side ---
    diff = evolution_checkpoint_bundle_diff(before, after_ok)
    expected = {
        "before_root": diff["before_root"],
        "after_root": diff["after_root"],
        "before_ids": ["a"],
        "after_ids": ["a", "b"],
        "digest": diff["digest"],
    }
    assert verify_evolution_checkpoint_bundle_diff(diff, expected) is True

    # change 'b' is added -> after side carries the proof. Splice int key
    # there; an equal-text valid credential occurs earlier in after.bundle.
    bad_diff = copy.deepcopy(diff)
    ch = next(c for c in bad_diff["changes"] if c["id"] == "b")
    ch["after"] = splice_int_key(copy.deepcopy(ch["after"]))
    # bytes unchanged -> declared digest still matches its own bytes
    assert json.dumps(bad_diff, ensure_ascii=False,
                      separators=(",", ":")) == json.dumps(
        diff, ensure_ascii=False, separators=(",", ":"))
    try:
        r = verify_evolution_checkpoint_bundle_diff(bad_diff, expected)
        print("VER int-key : returned", r, "(BUG: want ValueError)")
    except ValueError as exc:
        print("VER int-key : ValueError OK ->", str(exc)[:70])

    # tuple in change side
    bad_diff2 = copy.deepcopy(diff)
    ch2 = next(c for c in bad_diff2["changes"] if c["id"] == "b")
    ch2["after"] = splice_tuple_cases(copy.deepcopy(ch2["after"]))
    try:
        r = verify_evolution_checkpoint_bundle_diff(bad_diff2, expected)
        print("VER tuple   : returned", r, "(BUG: want ValueError)")
    except ValueError as exc:
        print("VER tuple   : ValueError OK ->", str(exc)[:70])

    # sanity: a normal truth mismatch still returns False
    false_diff = copy.deepcopy(diff)
    false_diff["digest"] = "f" * 64
    print("VER false digest ->",
          verify_evolution_checkpoint_bundle_diff(false_diff, expected))


if __name__ == "__main__":
    main()

