def _type_exact_key(value: Any) -> Any:
    """Build a type-preserving structural value key for one credential.

    The reuse identity must distinguish Python values that share a JSON
    spelling: a fact map keyed by the integer ``1`` must not merge with one
    keyed by the string ``"1"``, and a tuple must not merge with a list even
    though both serialize identically. Plain ``json.dumps(sort_keys=True)``
    folds exactly those cases, so it cannot key reuse.

    The key is a nested tuple tagged by Python type; dict members are sorted
    on the typed key pair, keeping key order irrelevant without merging
    differently-typed keys. It walks only the bounded leaf credential (the
    same tree the credential digest itself serializes); a whole deep proof
    is never serialized for keying. A non-JSON-native member (set, custom
    object, ...) raises ``TypeError``: such a value is structurally illegal,
    goes through full validation (which raises ``ValueError``), and is never
    cached.
    """
    if isinstance(value, dict):
        items = sorted(
            (_type_exact_key(k), _type_exact_key(v)) for k, v in value.items()
        )
        return ("dict", items)
    if isinstance(value, list):
        return ("list", tuple(_type_exact_key(item) for item in value))
    if isinstance(value, tuple):
        return ("tuple", tuple(_type_exact_key(item) for item in value))
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("int", value)
    if isinstance(value, float):
        return ("float", value)
    if isinstance(value, str):
        return ("str", value)
    raise TypeError(f"value of type {type(value).__name__} has no type-exact key")


